  color-scheme: dark;
  --ink: #e7e9e6;
  --muted: #8f9897;
  --line: rgba(231, 233, 230, 0.2);
  --acid: #78f4ff;
  --hot: #ff5b3d;
  --bg: #05070a;
  --mono: 'DM Mono', 'Courier New', monospace;
  --sans: 'Manrope', 'Segoe UI', sans-serif;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; background: var(--bg); }
body { margin: 0; min-width: 320px; background: var(--bg); color: var(--ink); font-family: var(--sans); }
a { color: inherit; text-decoration: none; }
button { color: inherit; font: inherit; }

.site-shell { position: relative; overflow: clip; min-height: 100vh; background: var(--bg); }
.noise { position: fixed; inset: 0; z-index: 5; pointer-events: none; opacity: .07; background-image: url(${___CSS_LOADER_URL_REPLACEMENT_0___}); }
.scene-layer { position: fixed; inset: 0; z-index: 0; pointer-events: none; background: radial-gradient(circle at 50% 46%, rgba(15, 43, 53, .42), transparent 42%), #05070a; }
.gundam-art { position: absolute; z-index: 1; top: -2vh; right: -2vw; width: 61vw; height: 112vh; object-fit: cover; object-position: 50% 12%; opacity: .9; filter: saturate(1.2) contrast(1.12) brightness(.82); -webkit-mask-image: linear-gradient(90deg, transparent 0%, #000 26%, #000 86%, transparent 100%), linear-gradient(180deg, transparent 0%, #000 8%, #000 84%, transparent 100%); mask-image: linear-gradient(90deg, transparent 0%, #000 26%, #000 86%, transparent 100%), linear-gradient(180deg, transparent 0%, #000 8%, #000 84%, transparent 100%); -webkit-mask-composite: source-in; mask-composite: intersect; transform: translate3d(0, 0, 0) scale(1.015); }
#scene-canvas { position: relative; z-index: 2; display: block; width: 100%; height: 100%; }
.scene-vignette { position: absolute; z-index: 3; inset: 0; background: linear-gradient(90deg, rgba(5, 7, 10, .82) 0%, rgba(5, 7, 10, .24) 42%, transparent 78%), radial-gradient(circle at 50% 42%, transparent 18%, rgba(5, 7, 10, .14) 64%, rgba(5, 7, 10, .88) 100%); }
.scene-grid { position: absolute; z-index: 4; inset: 0; opacity: .13; background-image: linear-gradient(rgba(120, 244, 255, .25) 1px, transparent 1px), linear-gradient(90deg, rgba(120, 244, 255, .25) 1px, transparent 1px); background-size: 72px 72px; mask-image: linear-gradient(to bottom, transparent 0%, black 26%, black 80%, transparent 100%); transform: perspective(500px) rotateX(58deg) scale(1.8) translateY(26%); transform-origin: center bottom; }
.scanline { position: absolute; z-index: 5; top: 0; left: 0; width: 100%; height: 1px; background: rgba(120, 244, 255, .55); box-shadow: 0 0 16px rgba(120, 244, 255, .8); opacity: .5; animation: scan 7s linear infinite; }
@keyframes scan { from { transform: translateY(-4vh); } to { transform: translateY(104vh); } }
.hud-corner, .scene-readout, .hud-crosshair { z-index: 6; position: absolute; color: var(--acid); font: 400 9px/1.55 var(--mono); letter-spacing: .14em; }
.hud-corner span, .scene-readout span:last-child { color: rgba(231, 233, 230, .45); }
.hud-top-left { top: 116px; left: 4vw; }
.hud-top-right { top: 116px; right: 4vw; text-align: right; }
.hud-crosshair { top: 47%; left: 50%; width: 72px; height: 72px; transform: translate(-50%, -50%); opacity: .55; }
.hud-crosshair::before, .hud-crosshair::after, .hud-crosshair i, .hud-crosshair b { position: absolute; content: ''; display: block; background: var(--acid); }
.hud-crosshair::before, .hud-crosshair::after { top: 50%; left: 0; width: 100%; height: 1px; }
.hud-crosshair::after { transform: rotate(90deg); }
.hud-crosshair i, .hud-crosshair b { top: 50%; left: 50%; width: 8px; height: 8px; border: 1px solid var(--hot); background: transparent; transform: translate(-50%, -50%) rotate(45deg); }
.hud-crosshair b { width: 42px; height: 42px; border-color: rgba(120, 244, 255, .42); }
.scene-readout { right: 4vw; bottom: 30px; display: grid; gap: 6px; text-align: right; }

.site-header { position: fixed; top: 0; left: 0; right: 0; z-index: 10; display: flex; align-items: center; justify-content: space-between; padding: 28px 4vw; mix-blend-mode: screen; }
.wordmark { font: 500 20px/1 var(--mono); letter-spacing: .08em; }
.wordmark span { color: var(--hot); }
.primary-nav { display: flex; gap: 36px; margin-left: auto; margin-right: 42px; font: 400 11px/1 var(--mono); text-transform: uppercase; letter-spacing: .12em; }
.primary-nav a { opacity: .7; transition: opacity .25s ease, color .25s ease; }
.primary-nav a:hover { color: var(--acid); opacity: 1; }
.menu-button { display: none; border: 0; background: transparent; padding: 10px 0 10px 10px; cursor: pointer; }
.menu-button span { display: block; width: 22px; height: 1px; margin: 5px 0; background: var(--ink); }

.section-frame { position: relative; z-index: 2; min-height: 100svh; padding: 0 8vw; }
.hero { display: flex; flex-direction: column; justify-content: center; }
.hero-copy { width: min(620px, 78vw); margin-top: -3vh; }
.eyebrow, .section-index, .hero-meta, .work-heading > span, .work-type, .site-footer, .model-status, .fallback-message { font: 400 10px/1.4 var(--mono); text-transform: uppercase; letter-spacing: .14em; }
.eyebrow { display: flex; align-items: center; gap: 10px; margin: 0 0 28px; color: var(--muted); }
.eyebrow-dot, .status-indicator { width: 6px; height: 6px; border-radius: 50%; background: var(--hot); box-shadow: 0 0 18px var(--hot); }
h1, h2, p { margin-top: 0; }
h1, h2 { font-weight: 500; letter-spacing: -.065em; }
h1 { margin-bottom: 30px; font-size: clamp(58px, 10vw, 150px); line-height: .85; }
h1 em, h2 em { color: var(--acid); font-style: normal; }
.hero-description { width: 260px; margin-left: 5px; color: var(--muted); font-size: 13px; line-height: 1.8; }
.hero-meta { position: absolute; right: 8vw; bottom: 8vh; display: grid; grid-template-columns: auto 82px auto; align-items: center; gap: 12px; color: var(--muted); font-size: 9px; }
.scroll-line { display: block; height: 1px; background: var(--line); }
.model-status { position: fixed; right: 4vw; bottom: 30px; z-index: 8; display: flex; gap: 9px; align-items: center; color: var(--muted); font-size: 9px; transition: opacity .4s ease; }
.status-indicator { width: 5px; height: 5px; }
.fallback-message { position: fixed; inset: auto 4vw 28px; z-index: 12; padding: 14px 16px; border: 1px solid var(--line); background: rgba(8, 9, 10, .88); color: var(--muted); }

.statement { display: grid; grid-template-columns: 1fr 2fr; align-items: center; padding-top: 5vh; }
.section-index { align-self: start; margin-top: 22vh; color: var(--acid); }
.statement-copy { max-width: 700px; }
h2 { margin-bottom: 28px; font-size: clamp(44px, 7vw, 104px); line-height: .95; }
.statement-copy p { max-width: 420px; margin-left: 8px; color: var(--muted); font-size: 15px; line-height: 1.8; }
.tag-row { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 34px; margin-left: 8px; }
.tag-row span { padding: 7px 9px; border: 1px solid rgba(120, 244, 255, .3); color: var(--acid); font: 9px var(--mono); letter-spacing: .12em; }
.work { padding-top: 18vh; padding-bottom: 18vh; }
.work-heading { display: flex; justify-content: space-between; margin-bottom: 7vh; border-bottom: 1px solid var(--line); padding-bottom: 18px; }
.work-heading .section-index { margin: 0; }
.work-heading > span { color: var(--muted); }
.work-item { display: grid; grid-template-columns: 8% 1fr 18% 30px; gap: 18px; align-items: center; min-height: 108px; border-bottom: 1px solid var(--line); transition: color .25s ease, padding .25s ease; }
.work-item:hover { padding-left: 10px; color: var(--acid); }
.work-number { color: var(--muted); font: 10px var(--mono); }
.work-name { font-size: clamp(20px, 3vw, 43px); letter-spacing: -.04em; }
.work-type { color: var(--muted); font-size: 9px; line-height: 1.4; }
.work-arrow { color: var(--acid); font-size: 20px; }
.contact { display: flex; flex-direction: column; justify-content: center; min-height: 90svh; }
.contact .section-index { margin: 0 0 12vh; }
.contact-copy { align-self: center; width: min(820px, 90vw); }
.contact-copy h2 { margin-bottom: 60px; font-size: clamp(58px, 10vw, 150px); }
.contact-link { display: inline-flex; align-items: center; gap: 18px; padding-bottom: 10px; border-bottom: 1px solid var(--acid); color: var(--acid); font: 400 13px var(--mono); }
.contact-link span { font-size: 18px; }
.site-footer { display: flex; justify-content: space-between; margin-top: auto; padding: 24px 0 30px; color: var(--muted); font-size: 9px; }

@media (max-width: 700px) {
  .site-header { padding: 22px 6vw; }
  .primary-nav { display: none; }
  .menu-button { display: block; }
  .section-frame { padding-right: 6vw; padding-left: 6vw; }
  .scene-vignette { background: radial-gradient(circle at 50% 42%, transparent 10%, rgba(5, 7, 10, .18) 55%, rgba(5, 7, 10, .92) 100%); }
  .gundam-art { top: 3vh; right: -22vw; width: 118vw; height: 82vh; object-position: 50% 10%; opacity: .72; filter: saturate(1.18) contrast(1.1) brightness(.78); }
  .hud-top-left, .hud-top-right { top: 92px; font-size: 8px; }
  .scene-readout { bottom: 18px; right: 6vw; }
  h1 { font-size: clamp(58px, 17vw, 94px); }
  .hero-copy { width: 88vw; }
  .hero-description { font-size: 12px; }
  .hero-meta { right: 6vw; bottom: 5vh; grid-template-columns: auto 42px auto; gap: 8px; font-size: 8px; }
  .model-status { right: 6vw; bottom: 19px; }
  .statement { display: block; padding-top: 20vh; }
  .statement .section-index { margin: 0 0 23vh; }
  .statement-copy p { margin-left: 0; }
  .work { padding-top: 16vh; padding-bottom: 22vh; }
  .work-item { grid-template-columns: 30px 1fr 22px; min-height: 110px; gap: 10px; }
  .work-type { grid-column: 2; grid-row: 2; }
  .work-arrow { grid-column: 3; grid-row: 1 / span 2; }
  .contact .section-index { margin-bottom: 18vh; }
  .contact-copy { width: 100%; }
  .contact-copy h2 { font-size: clamp(58px, 16vw, 94px); margin-bottom: 44px; }
  .site-footer { display: grid; gap: 10px; font-size: 8px; }
}
